              nombre: rolCausa.demanda.materia.nombre,
            }
          : null,
        ejecutados: rolCausa.demanda.ejecutados
          ? rolCausa.demanda.ejecutados.map((ej: any) => ({
              id: ej.id,
              nombre: ej.nombre,
              rut: ej.rut,
              direccion: ej.direccion ?? null,
              comuna: ej.comunas
                ? {
                    id: ej.comunas.id,
