      ? new Date(Math.max(...allDates.map((d: any) => d.getTime()))).toISOString()
      : null

  const kpis = {
    diligenciasTotal: rolCausa.diligencias.length,
    diligenciasPendientes: rolCausa.diligencias.filter((d: any) => d.estado === 'pendiente').length,
