  return {
    rol,
    tribunal,
    demanda,
    abogado,
    ultimaActividad,
    kpis,
    resumen: {
      diligencias: resumenDiligencias,
      documentos: resumenDocumentos,
      notas: resumenNotas,
      recibos: resumenRecibos,
    },
  }
}

