        y: stampY,
        width: stampDims.width,
        height: stampDims.height,
      })
    } catch (error) {
      console.warn('Error embedding stamp image:', error)
    }
  }
  
  const pdfBytes = await doc.save()
  return Buffer.from(pdfBytes).toString('base64')
}

/**
