import { PDFDocument, StandardFonts, degrees, rgb } from 'pdf-lib'
import { wrapText } from '@/lib/pdf/textLayout'

export type MembretePlacement = '1' | '2' | '3' | '4' | '5' | '6'
export type MembretePageSize = 'oficio' | 'carta'

export type MembreteVariables = {
  nombre: string
  direccion: string
  causa: string
  rol: string
  caratulado: string
  abogado: string
}

const PAGE_SIZES: Record<MembretePageSize, [number, number]> = {
  carta: [612, 792],
  oficio: [612, 1008],
}

function resolveBlockPlacement(
  pageWidth: number,
  pageHeight: number,
  placement: MembretePlacement
) {
  const marginX = 42
  const blockWidth = 252
  const blockHeight = 176
  const topY = pageHeight - 58
  const middleY = pageHeight / 2 + blockHeight / 2
  const bottomY = 238
  const leftX = marginX
  const rightX = pageWidth - marginX - blockWidth

  switch (placement) {
    case '2':
      return { x: rightX, y: topY, width: blockWidth, rotate: false }
    case '3':
      return { x: leftX, y: bottomY, width: blockWidth, rotate: false }
    case '4':
      return { x: rightX, y: bottomY, width: blockWidth, rotate: false }
    case '5':
      return { x: 56, y: middleY + 92, width: blockWidth, rotate: true }
    case '6':
      return { x: pageWidth - 56, y: middleY - blockWidth + 92, width: blockWidth, rotate: true }
    case '1':
    default:
      return { x: leftX, y: topY, width: blockWidth, rotate: false }
  }
}

export async function buildMembretePdf(
  variables: MembreteVariables,
  placement: MembretePlacement,
  pageSize: MembretePageSize
): Promise<string> {
  const doc = await PDFDocument.create()
  const page = doc.addPage(PAGE_SIZES[pageSize])
  const font = await doc.embedFont(StandardFonts.TimesRoman)
  const fontBold = await doc.embedFont(StandardFonts.TimesRomanBold)
  const pageWidth = page.getSize().width
  const pageHeight = page.getSize().height
  const block = resolveBlockPlacement(pageWidth, pageHeight, placement)

  const fields = [
    { label: 'NOMBRE', value: variables.nombre },
    { label: 'DIRECCIÓN', value: variables.direccion },
    { label: 'CAUSA', value: variables.causa },
    { label: 'ROL N°:', value: variables.rol },
    { label: 'CARATULADO', value: variables.caratulado },
    { label: 'ABOGADO', value: variables.abogado },
  ]

  const labelSize = 8.5
  const valueSize = 8.5
  const lineGap = 11
  const labelWidth = 70
  let y = block.y

  const drawText = (text: string, x: number, textY: number, options: { bold?: boolean } = {}) => {
    page.drawText(text, {
      x,
      y: textY,
      size: options.bold ? labelSize : valueSize,
      font: options.bold ? fontBold : font,
      color: rgb(0, 0, 0),
      rotate: block.rotate ? degrees(90) : undefined,
    })
  }

  const stepDown = (amount: number) => {
    y -= amount
  }

  for (const field of fields) {
    const valueX = block.x + labelWidth
    drawText(field.label, block.x, y, { bold: true })

    const lines = wrapText(field.value || '-', block.width - labelWidth, font, valueSize)
    lines.forEach((line, index) => {
      if (line !== '__BLANK__') {
        drawText(line, valueX, y - index * lineGap)
      }
    })

    stepDown(Math.max(lineGap, lines.length * lineGap) + 2)
  }

  stepDown(10)
  drawText('Notifico a ud. lo siguiente:', block.x, y)

  const pdfBytes = await doc.save()
  return Buffer.from(pdfBytes).toString('base64')
}

import { NextRequest, NextResponse } from 'next/server'

import { getCurrentUserWithOffice } from '@/lib/auth-server'
import { prisma } from '@/lib/prisma'
import { buildMembretePdf } from '@/lib/pdf/membrete'
import { MembreteGenerateSchema } from '@/lib/validations/rol-workspace'

export const dynamic = 'force-dynamic'

export async function POST(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const user = await getCurrentUserWithOffice()

    if (!user) {
      return NextResponse.json({ ok: false, error: 'No autorizado' }, { status: 401 })
    }

    const raw = await req.json().catch(() => ({}))
    const parsed = MembreteGenerateSchema.safeParse(raw)

    if (!parsed.success) {
      return NextResponse.json({ ok: false, error: parsed.error.format() }, { status: 400 })
    }

    const data = parsed.data

    const rol = await prisma.rolCausa.findFirst({
      where: {
        id: params.id,
        officeId: user.officeId,
      },
      include: {
        tribunal: {
          select: {
            nombre: true,
          },
        },
        demanda: {
          include: {
            abogados: {
              select: {
                nombre: true,
              },
            },
            ejecutados: {
              include: {
                comunas: {
                  select: {
                    nombre: true,
                  },
                },
              },
            },
          },
        },
      },
    })

    if (!rol || !rol.demanda) {
      return NextResponse.json(
        { ok: false, error: 'Rol no encontrado o sin demanda asociada' },
        { status: 404 }
      )
    }

    const ejecutado = rol.demanda.ejecutados.find(item => item.id === data.ejecutadoId)

    if (!ejecutado) {
      return NextResponse.json(
        { ok: false, error: 'Ejecutado no encontrado para este rol' },
        { status: 404 }
      )
    }

    const direccion = [ejecutado.direccion, ejecutado.comunas?.nombre]
      .filter(Boolean)
      .join(', ')

    const pdfBase64 = await buildMembretePdf(
      {
        nombre: ejecutado.nombre,
        direccion,
        causa: [rol.tribunal?.nombre, rol.rol].filter(Boolean).join(' / '),
        rol: rol.rol,
        caratulado: rol.demanda.caratula,
        abogado: rol.demanda.abogados?.nombre ?? '',
      },
      data.placement,
      data.pageSize
    )

    const documento = await prisma.documento.create({
      data: {
        rolId: rol.id,
        nombre: `Membrete ${ejecutado.nombre}`,
        tipo: 'Membrete',
        pdfId: pdfBase64,
        version: 1,
      },
    })

    return NextResponse.json({
      ok: true,
      data: {
        id: documento.id,
        nombre: documento.nombre,
        tipo: documento.tipo,
        version: documento.version,
        hasPdf: !!documento.pdfId,
        createdAt: documento.createdAt.toISOString(),
      },
    })
  } catch (error) {
    console.error('Error generando membrete:', error)
    return NextResponse.json(
      { ok: false, error: 'Error al generar el membrete' },
      { status: 500 }
    )
  }
}

