    setSelectedEjecutadoId(ejecutados[0]?.id ?? '')
  }, [ejecutados])

  const selectedEjecutado = useMemo(
    () => ejecutados.find(item => item.id === selectedEjecutadoId) ?? null,
    [ejecutados, selectedEjecutadoId]
  )

